% حقيبة 0/1: نختار عناصر لتعظيم القيمة دون تجاوز السعة
weights = [2, 3, 4, 5];
values = [3, 4, 5, 6];
capacity = 5;
n = length(weights);
dp = zeros(n+1, capacity+1);
for i = 1:n
  for w = 1:capacity
    if weights(i) <= w
      dp(i+1, w+1) = max(dp(i, w+1), values(i) + dp(i, w-weights(i)+1));
    else
      dp(i+1, w+1) = dp(i, w+1);
    end
  end
end
result = dp(n+1, capacity+1);
printf('Maximum value: %d\n', result);

