global memo;
memo = containers.Map();  % خريطة للتخزين
function y = fib(n)
    global memo;
    if isKey(memo, num2str(n))
        y = memo(num2str(n));
        return;
    endif
    if n <= 1
        y = n;
    else
        y = fib(n-1) + fib(n-2);
    endif
    memo(num2str(n)) = y;  % نخزن النتيجة
endfunction
